create table public.bhl_rules (
 id smallint primary key check (id=1),
 title text not null check (char_length(trim(title)) between 1 and 160),
 introduction text not null default '' check (char_length(introduction)<=1000),
 sections jsonb not null check (jsonb_typeof(sections)='array' and jsonb_array_length(sections) between 1 and 100 and octet_length(sections::text)<=500000),
 revision integer not null default 1,
 updated_at timestamptz not null default now()
);
alter table public.bhl_rules enable row level security;
revoke all on public.bhl_rules from anon,authenticated;
grant select on public.bhl_rules to anon,authenticated;
grant update(title,introduction,sections) on public.bhl_rules to authenticated;
create policy rules_public_read on public.bhl_rules for select to anon,authenticated using(true);
create policy rules_admin_update on public.bhl_rules for update to authenticated
using(exists(select 1 from public.bhl_profiles p where p.user_id=(select auth.uid()) and p.role='admin'))
with check(exists(select 1 from public.bhl_profiles p where p.user_id=(select auth.uid()) and p.role='admin'));
create function public.bhl_rules_guard() returns trigger language plpgsql security invoker set search_path='' as $$
declare item jsonb; seen text[]:=array[]::text[];
begin
 if not exists(select 1 from public.bhl_profiles p where p.user_id=(select auth.uid()) and p.role='admin') then
  raise exception 'Accès administrateur requis' using errcode='42501';
 end if;
 for item in select value from jsonb_array_elements(new.sections) loop
  if jsonb_typeof(item)<>'object' or
     jsonb_typeof(item->'id') is distinct from 'string' or
     jsonb_typeof(item->'category') is distinct from 'string' or
     jsonb_typeof(item->'title') is distinct from 'string' or
     jsonb_typeof(item->'body') is distinct from 'string' or
     (item->>'id') !~ '^[A-Za-z0-9][A-Za-z0-9.-]{0,39}$' or
     char_length(trim(item->>'category')) not between 1 and 80 or
     char_length(trim(item->>'title')) not between 1 and 160 or
     char_length(trim(item->>'body')) not between 1 and 40000 or
     (item->>'id')=any(seen) then
    raise exception 'Article invalide : numéro unique, catégorie, titre et texte requis' using errcode='22023';
  end if;
  seen:=array_append(seen,item->>'id');
 end loop;
 new.id:=old.id;new.revision:=old.revision+1;new.updated_at:=now();
 return new;
end $$;
revoke all on function public.bhl_rules_guard() from public,anon,authenticated;
create trigger bhl_rules_guard before update on public.bhl_rules for each row execute function public.bhl_rules_guard();

insert into public.bhl_rules(id,title,introduction,sections) values (1,'Règlements','Les règles de la Béliveau Hockey League.', $bhlrules$[{"id": "1.1", "category": "Général", "title": "Bourses", "body": "<p>Le prix est de 75$ pour pouvoir participer à une saison de la BHL.</p><p>75$x16 poolers = 1200$</p><p>Champion 52,5% = 630$</p><p>Finaliste 13% = 155$</p><p>1er saison 23% = 275$</p><p>2e saison 11,5% = 140$</p>"}, {"id": "1.2", "category": "Général", "title": "Calendrier", "body": "<p>La BHL utilise un calendrier personnalisé pour ses propres affrontements. Notamment, des semaines peuvent être combinées à d&#x27;autres pour améliorer la qualité des duels et de la représentation d&#x27;une victoire dans le pool. (Ex. Semaine du match des étoiles) La BHL offre 3 duels par équipe à chaque période du calendrier.</p>"}, {"id": "1.3", "category": "Général", "title": "Séries éliminatoires", "body": "<p>Il est à noter que la finale de la BHL se joue sur deux semaines et que le dernier match de chaque équipe LNH est soustrait du calendrier des séries de la BHL si la situation le permet sans soustraire trop de matchs dans l&#x27;ensemble. 8 équipes participent aux séries de la BHL.</p>"}, {"id": "1.4", "category": "Général", "title": "Pointage", "body": "<p>La BHL utilise le système de pointage suivant:</p><h3>Joueurs</h3><p>But = 3</p><p>Passe = 2.5</p><p>Tir = 0.3</p><p>Takeaway = 0.1</p><p>Hit = 0.1</p><p>Tir bloqué = 0.2</p><p>Mise en jeu gagnée = 0.05 *Centres seulement</p><h3>Gardiens</h3><p>Victoire = 4</p><p>Buts accordés = -1</p><p>Passe = 2.5</p><p>But = 3</p><p>Arrêts = 0.2</p><p>Blanchissage = 4</p>"}, {"id": "1.5", "category": "Général", "title": "Entre-saison", "body": "<p>Voici l&#x27;ordre des activités de la BHL durant l&#x27;entre-saison</p><p>1. Votes pour les règlements et les trophées</p><p>2. Création de la nouvelle saison sur Fantrax</p><p>3. Libération des Liste des blessés (IR)</p><p>4. Ouverture du marché des échanges (avril-mai)</p><p>5. Confirmation des protections (septembre) et mise à jour des éligibilités espoir pour la nouvelle saison</p><p>6. Repêchage de la BHL</p><p>7. Lancement de la nouvelle saison</p>"}, {"id": "2.1", "category": "Alignements", "title": "Alignements", "body": "<p>La composition des formations de la BHL ressemble à ceci:</p><p>4 Centres</p><p>4 Ailiers droit</p><p>4 Ailiers gauche</p><p>6 Défenseurs</p><p>1 Gardien</p><p>7 Joueurs supplémentaires</p><p>4 Espoirs</p><p>Le seul moment qu&#x27;une formation peut dépasser le nombre de 30 joueurs est lorsqu&#x27;il y en a un (ou deux) sur la Liste des blessés(IR).</p>"}, {"id": "2.2", "category": "Alignements", "title": "Liste des blessés", "body": "<p>Les joueurs ayant un drapeau rouge sur Fantrax sont éligibles à être mis sur la Liste des blessés. Il est cependant demandé de s&#x27;assurer qu&#x27;à chaque lundi (ou toute autre journée où les alignements sont confirmés pour la semaine) notre Liste des blessés (IR) soit mise à jour en libérant les joueurs en santé.</p><p>Une formation peut garder un joueur sur sa Liste des blessés (IR) jusqu’à la fin des séries de la BHL.</p>"}, {"id": "2.3", "category": "Alignements", "title": "Espoirs", "body": "<p>En tout temps, une formation de la BHL peut placer quatre joueurs (c&#x27;était trois suite au draft 2022 de la BHL) ayant un titre d’espoirs dans leur club école. Ces joueurs peuvent être rappelés ou retournés au club école tant et aussi longtemps qu’ils ont le statut d’espoir. Le statut d&#x27;espoir est actualisé uniquement entre les saisons.</p><p>Pour être éligible à un titre d&#x27;espoir pour une saison BHL, un joueur doit respecter ces deux conditions :</p><p>-Maximum de 25 ans au 15 septembre du début de la saison de la LNH</p><p>-Maximum de 100 matchs LNH en carrière ainsi que 60 matchs pour un gardien</p><h3>ÉLIGIBLE</h3><p>Patineur 100 parties LNH</p><p>Gardien 60 parties LNH</p><p>25 ans le 15 septembre de la nouvelle saison</p><h3>NON-ÉLIGIBLE</h3><p>Patineur 101 parties LNH</p><p>Gardien 61 parties LNH</p><p>26 ans le 15 septembre de la nouvelle saison</p><p>*Ancienne règle</p><p>De 2022-2023 à 2024-2025</p><p>-Maximum de 25 ans au 15 septembre du début de la saison de la LNH</p><p>-Maximum de 60 parties LNH en carrière ainsi que 35 parties pour un gardien</p><p>-3 places espoirs</p>"}, {"id": "2.4", "category": "Alignements", "title": "Gardiens", "body": "<p>Un maximum de 2 gardiens est permis dans une formation de la BHL. Les exceptions sont:</p><p>- Un troisième gardien au statut d’espoir qui ne peut qu’être utilisé si l’un deux autres gardiens est libéré ou placé sur la liste des blessés (IR)</p><p>- Un troisième gardien acquis pendant que l’un des deux gardiens de la formation est placé sur la liste des blessés (IR)</p>"}, {"id": "2.5", "category": "Alignements", "title": "Protections", "body": "<p>Avant chaque début de saison, chaque formation de la BHL est invitée à choisir une quantité de joueurs qu’ils pourront garder pour la saison suivante. Les protections vont comme suit:</p><p>8 attaquants</p><p>4 défenseurs</p><p>1 gardien</p><p>4 espoirs</p>"}, {"id": "3.1", "category": "Transactions", "title": "Transactions", "body": "<p>En tout temps, une transaction dans BHL doit contenir le même nombre de joueurs et de choix au repêchage pour les deux clubs. Le seul temps ou il est permis de ne pas inclure le même nombre de joueurs est durant l’entre-saison. Il est obligatoire d’inclure le même nombre de choix dans un échange autant durant la saison que durant l’entre-saison.</p><p>Lorsqu&#x27;il y a entente entre deux directeurs généraux, il faut en faire l&#x27;annonce sur le groupe Facebook de la BHL et compléter l&#x27;échange sur Fantrax.</p><p>Dans un cas extrême uniquement, les autres poolers pourront protester à l’aide d’un vote s’ils jugent qu’une transaction semble totalement illogique et qu’elle place l’avenir d’un pool en péril.</p>"}, {"id": "3.2", "category": "Transactions", "title": "Date limite des échanges", "body": "<p>La date limite des échanges n&#x27;est pas fixe, mais l&#x27;heure limite est à 22h dans tous les cas. Dès qu&#x27;il est 22h, plus aucun échange ne sera accepté. Habituellement, la date limite sera un jeudi environ à 4 périodes de la fin de la saison régulière de la BHL. Elle peut être plus tard dans la saison selon les réalités du calendrier le la LNH comme les pauses olympiques etc.</p><p>En cas de transaction dans les dernières secondes de la date limite des échanges, toute annonce de l&#x27;échange avant la limite de 22h sera acceptée pour qu&#x27;elle soit valide. Un échange doit être annoncé sur le groupe Facebook ou encore Fantrax avant l&#x27;heure limite même si le processus complet n&#x27;est pas complété (exemple : publier sur Facebook à 21h59 et compléter l&#x27;échanger sur Fantrax après 22h). L&#x27;annonce sur Messenger ne sera pas acceptée comme annonce officielle avant 22h, soyez simplement prêt à publier rapidement sur le groupe Facebook ou à envoyer et accepter la transaction sur Fantrax avant 22h. L&#x27;option de publier rapidement sur le groupe Facebook est la plus rapide et efficace pour un échange conclu dans les dernières secondes de la date limite. Pour être valide, la publication Facebook se doit de comporter tous les éléments de la transaction.</p>"}, {"id": "3.3", "category": "Transactions", "title": "Waivers/agents libres", "body": "<p>Une équipe de la BHL a le droit de réclamer un agent libre par semaine, en autant que la limite de joueurs permise soit respectée.</p><p>Il y a deux moyens qu’un joueur soit forcé de passer par le processus de Waivers (ballotage), qui est un système implanté pour donner une meilleure chance aux formations moins bien classées de s’améliorer:</p><p>- Tous les agents libres sont envoyés vers le ballotage entre dimanche 23h55 et lundi 10h00. Ce procédé a pour but de donner une chance égale a tout le monde de se manifester pour réclamer un joueur disponible en vue de la nouvelle période d’affrontements BHL.</p><p>À noter qu’aucune réclamation d’agent libre n’est permise avant qu’une période de la saison régulière de la BHL soit écoulée.</p><p>Une fois les séries de la BHL amorcées, seulement les équipes encore actives en séries peuvent réclamer des agents libres sauf si c’est un joueur au statut d’espoir.</p>"}, {"id": "3.4", "category": "Transactions", "title": "Choix au repêchage", "body": "<p>Une équipe de la BHL peut échanger des choix au repêchage à tout moment de la saison, en autant que le même nombre de choix soit inclus de l’autre côté de la transaction.</p><p>Depuis le début de notre troisième saison, il n’est pas obligatoire que chaque formation ait un choix espoir en tout temps. On doit simplement avoir le même nombre de choix au total dans chaque formation. Donc, exemple, une formation en reconstruction peut dorénavant avoir plus d’un choix espoir.</p>"}, {"id": "3.5", "category": "Transactions", "title": "Repêchage", "body": "<p>À chaque début de saison, la BHL procédera au repêchage officiel du pool. Ce repêchage est divisé en deux parties, soit le repêchage espoir (1e ronde) et le repêchage principal (2e ronde et subséquentes).</p><p>Les tirages sont faits en même temps que le lancement des séries éliminatoires de la BHL avec l’aide du site www.draftpicklottery.com. Voici ci-dessous les chances, par position au classement, pour chacun des tirages:</p><h3>Repêchage principal</h3><p>16e = 25%</p><p>15e = 20%</p><p>14e = 15%</p><p>13e = 10%</p><p>12e = 9%</p><p>11e = 8%</p><p>10e = 7%</p><p>9e = 6%</p><h3>Repêchage espoir</h3><p>16e = 32%</p><p>15e = 21%</p><p>14e = 15%</p><p>13e = 10%</p><p>12e = 8.5%</p><p>11e = 6.5%</p><p>10e = 4.5%</p><p>9e = 2.5%</p><p>Pour les loteries, à noter qu’elles servent à déterminer le top 3 du repêchage principal et du repêchage espoir.</p>"}]$bhlrules$::jsonb);
